        wr_dbl(Un, LocalVar->WE.v_h);
        wr_dbl_array(Un, &LocalVar->WE.P[0][0], 9);
        wr_dbl_array(Un, &LocalVar->WE.xh[0][0], 3);
        wr_dbl_array(Un, &LocalVar->WE.K[0][0], 3);

        wr_dbl_array(Un, LocalVar->FP.lpf1_a1, 1024);
        wr_dbl_array(Un, LocalVar->FP.lpf1_a0, 1024);
        wr_dbl_array(Un, LocalVar->FP.lpf1_b1, 1024);
        wr_dbl_array(Un, LocalVar->FP.lpf1_b0, 1024);
        wr_dbl_array(Un, LocalVar->FP.lpf1_InputSignalLast, 1024);
        wr_dbl_array(Un, LocalVar->FP.lpf1_OutputSignalLast, 1024);
        wr_dbl_array(Un, LocalVar->FP.lpf2_a2, 1024);
        wr_dbl_array(Un, LocalVar->FP.lpf2_a1, 1024);
        wr_dbl_array(Un, LocalVar->FP.lpf2_a0, 1024);
        wr_dbl_array(Un, LocalVar->FP.lpf2_b2, 1024);
        wr_dbl_array(Un, LocalVar->FP.lpf2_b1, 1024);
        wr_dbl_array(Un, LocalVar->FP.lpf2_b0, 1024);
