        wr_dbl_array(Un, LocalVar->FP.lpfV_b0, 1024);
        wr_dbl_array(Un, LocalVar->FP.lpfV_InputSignalLast2, 1024);
        wr_dbl_array(Un, LocalVar->FP.lpfV_OutputSignalLast2, 1024);
        wr_dbl_array(Un, LocalVar->FP.lpfV_InputSignalLast1, 1024);
        wr_dbl_array(Un, LocalVar->FP.lpfV_OutputSignalLast1, 1024);
        wr_dbl_array(Un, LocalVar->FP.hpf_InputSignalLast, 1024);
